import math

PHI = (1 + math.isqrt(5) ) / 2


def _pairs(limit):
    loses = set()
    n = 0
    while True:
        xi = (n * (1 + 5 ** 0.5)) / 2.0
        x = int(xi)
        y = x + n
        if x > limit:
            break
        if n > 0:
            loses.add((x, y))
            loses.add((y, x))
        n += 1
    return loses


def solve(text: str) -> str:
    data = text.split()
    a = int(data[0])
    b = int(data[1])
    limit = max(a, b)
    loses = _pairs(limit)
    if (a, b) in loses:
        return 'LOSE'
    for i in range(0, a + 1):
        for j in range(0, b + 1):
            if i == 0 and j == 0:
                continue
            if (i > 0 and j > 0 and i != j):
                continue
            if (a - i, b - j) in loses:
                return 'WIN %d %d' % (i, j)
    return 'WIN 0 0'
